function App() {
  // Illustrative — Next.js maps the app/ folder to URLs:
  const routes = [
    ["app/page.tsx", "/"],
    ["app/about/page.tsx", "/about"],
    ["app/blog/[slug]/page.tsx", "/blog/:slug"],
    ["app/api/hello/route.ts", "/api/hello (endpoint)"],
  ];
  return (
    <table style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>
      <tbody>
        {routes.map(([file, url]) => (
          <tr key={file}><td style={{ paddingRight: 16 }}>{file}</td><td>{url}</td></tr>
        ))}
      </tbody>
    </table>
  );
}

