function App() {
  const answers = {
    'Need good SEO + fast first paint': 'Server rendering (SSR/SSG)',
    'Need a backend API endpoint': 'Route Handler (app/api/.../route.ts)',
    'Need optimized, lazy-loaded images': 'next/image component',
    'Need a /pricing page at that URL': 'File-based routing (app/pricing/page.tsx)',
  };
  return (
    <ul style={{ fontFamily: 'system-ui', padding: 16 }}>
      {Object.entries(answers).map(([k, v]) => <li key={k}><b>{k}:</b> {v}</li>)}
    </ul>
  );
}

