// Treating a Next.js page like a plain client SPA:
// 'use client'  <-- forces client rendering for the whole page
function App() {
  const [posts, setPosts] = useState(null);
  useEffect(() => {
    setTimeout(() => setPosts(['Post A', 'Post B']), 500);
  }, []);
  if (!posts) return <p>Loading…</p>; // crawlers see only this
  return <ul>{posts.map(p => <li key={p}>{p}</li>)}</ul>;
}

